def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    h = len(grid)
    w = len(grid[0]) if h else 0

    out = [row[:] for row in grid]

    # A horizontal run of exactly three 4s is a candidate bar.
    # If the middle cell of that bar also has 4s directly above and below,
    # recolor the 3x3 cross (the bar plus the vertical neighbours) to 8.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == 4:
                start = c
                while c < w and grid[r][c] == 4:
                    c += 1
                length = c - start

                if length == 3:
                    mid = start + 1
                    if 0 < r < h - 1:
                        if grid[r - 1][mid] == 4 and grid[r + 1][mid] == 4:
                            out[r - 1][mid] = 8
                            out[r][mid - 1] = 8
                            out[r][mid] = 8
                            out[r][mid + 1] = 8
                            out[r + 1][mid] = 8
            else:
                c += 1

    return out

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the border colour (also the dominant colour in these tasks).
    bg = int(g[0, 0])

    # Non-background mask.
    mask = g != bg

    # 8-connected components of non-background cells.
    comp_id = -np.ones((h, w), dtype=int)
    comps = []
    cid = 0
    for r in range(h):
        for c in range(w):
            if mask[r, c] and comp_id[r, c] == -1:
                q = deque([(r, c)])
                comp_id[r, c] = cid
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w:
                                if mask[ny, nx] and comp_id[ny, nx] == -1:
                                    comp_id[ny, nx] = cid
                                    q.append((ny, nx))
                comps.append(cells)
                cid += 1

    out = g.copy()

    for cells in comps:
        twos = [(r, c) for (r, c) in cells if g[r, c] == 2]
        if not twos:
            continue

        for r, c in cells:
            if g[r, c] == 2:
                continue

            # Nearest 2 in the same component by Manhattan distance.
            best = None
            best_d = None
            for tr, tc in twos:
                d = abs(r - tr) + abs(c - tc)
                if best_d is None or d < best_d:
                    best_d = d
                    best = (tr, tc)

            tr, tc = best
            nr = 2 * tr - r
            nc = 2 * tc - c

            if 0 <= nr < h and 0 <= nc < w:
                # Do not overwrite original non-background cells.
                if not mask[nr, nc]:
                    out[nr, nc] = g[r, c]

    return out.tolist()

