        return []

    h, w = len(grid), len(grid[0])
    used = [[False] * w for _ in range(h)]
    objects = []

    # Find all 4x4 filled or hollow square objects.
    for r in range(h - 3):
        for c in range(w - 3):
            block = [grid[r + i][c:c + 4] for i in range(4)]

            nonzeros = [v for row in block for v in row if v != 0]
            if not nonzeros:
                continue
            if len(set(nonzeros)) != 1:
                continue

            color = nonzeros[0]

            is_solid = True
            is_hollow = True

            for i in range(4):
                for j in range(4):
                    v = block[i][j]

                    if v != color:
                        is_solid = False

                    if i in (0, 3) or j in (0, 3):
                        if v != color:
                            is_hollow = False
                    else:
                        if v != 0:
                            is_hollow = False

            if is_solid:
                kind = 1
            elif is_hollow:
                kind = 0
            else:
                continue

            # Avoid duplicate detections of the same object.
            if any(
                used[r + i][c + j]
                for i in range(4)
                for j in range(4)
                if block[i][j] != 0
            ):
                continue

            for i in range(4):
                for j in range(4):
                    if block[i][j] != 0:
                        used[r + i][c + j] = True

            objects.append((r, c, kind, block))

    hollows = [o for o in objects if o[2] == 0]
    solids = [o for o in objects if o[2] == 1]

    # Sort each group top-to-bottom, then left-to-right.
    hollows.sort(key=lambda x: (x[0], x[1]))
    solids.sort(key=lambda x: (x[0], x[1]))

    rows = max(len(hollows), len(solids))
    if rows == 0:
        return []

    out = [[0] * 8 for _ in range(rows * 4)]

    for idx, (_, _, _, block) in enumerate(hollows):
        base = idx * 4
        for i in range(4):
            for j in range(4):
                out[base + i][j] = block[i][j]

    for idx, (_, _, _, block) in enumerate(solids):
        base = idx * 4
        for i in range(4):
            for j in range(4):
                out[base + i][4 + j] = block[i][j]

    return out

