    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find the vertical separator line:
    # a column containing the same non-zero colour in most rows.
    best_col, best_color, best_count = -1, -1, 0
    for c in range(w):
        col = g[:, c]
        for color in range(1, 10):
            cnt = int(np.sum(col == color))
            if cnt > best_count:
                best_count, best_col, best_color = cnt, c, color

    if best_col == -1 or best_count < max(1, h // 2):
        return out.tolist()

    line_col = best_col
    line_color = best_color

    # Decide which side contains the source bars.
    left_mask = np.zeros((h, w), dtype=bool)
    right_mask = np.zeros((h, w), dtype=bool)
    left_mask[:, :line_col] = True
    right_mask[:, line_col + 1:] = True

    left_count = int(np.sum((g != 0) & left_mask))
    right_count = int(np.sum((g != 0) & right_mask))
    source_left = left_count >= right_count

    # Clear the target side; the line and source side are preserved.
    if source_left:
        out[:, line_col + 1:] = 0
    else:
        out[:, :line_col] = 0

    # For each row, project source runs to the target side.
    for r in range(h):
        assigned = set()

        if source_left:
            # Source columns from nearest to farthest from the line.
            src_cols = range(line_col - 1, -1, -1)
            # Target columns from nearest to farthest from the line.
            def target_col(p: int) -> int:
                return line_col + 1 + p
        else:
            src_cols = range(line_col + 1, w)
            def target_col(p: int) -> int:
                return line_col - 1 - p

        i = 0
        n = len(list(src_cols))
        while i < n:
            c = src_cols[i]
            color = int(g[r, c])
            if color == 0:
                i += 1
                continue

            # Measure the length of this same-colour run.
            j = i
            while j + 1 < n:
                c2 = src_cols[j + 1]
                if int(g[r, c2]) == color:
                    j += 1
                else:
                    break
            run_len = j - i + 1

            # This run claims target positions 0, run_len, 2*run_len, ...
            p = 0
            while True:
                tc = target_col(p)
                if tc < 0 or tc >= w:
                    break
                if tc not in assigned:
                    out[r, tc] = color
                    assigned.add(tc)
                p += run_len

            i = j + 1

    return out.tolist()

