    cid = 0
    for r in range(h):
        for c in range(w):
            if a[r, c] == 1 and comp[r, c] == 0:
                cid += 1
                stack = [(r, c)]
                comp[r, c] = cid
                while stack:
                    y, x = stack.pop()
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w:
                                if a[ny, nx] == 1 and comp[ny, nx] == 0:
                                    comp[ny, nx] = cid
                                    stack.append((ny, nx))

    # 4-connected background regions
    bg = np.zeros((h, w), dtype=int)
    bid = 0
    for r in range(h):
        for c in range(w):
            if a[r, c] == 4 and bg[r, c] == 0:
                bid += 1
                stack = [(r, c)]
                bg[r, c] = bid
                while stack:
                    y, x = stack.pop()
                    for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if a[ny, nx] == 4 and bg[ny, nx] == 0:
                                bg[ny, nx] = bid
                                stack.append((ny, nx))

    # exterior background id
    ext = 0
    for r in range(h):
        for c in range(w):
            if a[r, c] == 4 and (r == 0 or r == h - 1 or c == 0 or c == w - 1):
                ext = bg[r, c]
                break
        if ext:
            break

    # For each component, find holes and exterior border cells
    for cid in range(1, cid + 1):
        mask = (comp == cid)
        if not mask.any():
            continue

        # background cells 8-adjacent to this component
        adj = np.zeros((h, w), dtype=bool)
        for r in range(h):
            for c in range(w):
                if mask[r, c]:
                    y0, y1 = max(0, r - 1), min(h, r + 2)
                    x0, x1 = max(0, c - 1), min(w, c + 2)
                    adj[y0:y1, x0:x1] |= True
        adj &= (a == 4)

        # holes: non-exterior background regions adjacent to component
        hole = np.zeros((h, w), dtype=bool)
        for b in range(1, bid + 1):
            if b == ext:
                continue
            if np.any(adj & (bg == b)):
                hole |= (bg == b)

        # exterior border: exterior background cells 8-adjacent to component
        border = adj & (bg == ext)

        if hole.any():
            out[mask] = 8
            out[hole] = 6
        # else original 1s remain 1

        out[border] = 2

    return out.tolist()

