from typing import List

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    H, W = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Background is the most frequent colour.
    bg = Counter(cell for row in grid for cell in row).most_common(1)[0][0]

    # Connected components of non-background cells (4-neighbourhood).
    seen = [[False] * W for _ in range(H)]
    components = []

    for r in range(H):
        for c in range(W):
            if seen[r][c] or grid[r][c] == bg:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < H and 0 <= nx < W:
                        if not seen[ny][nx] and grid[ny][nx] != bg:
                            seen[ny][nx] = True
                            stack.append((ny, nx))
            components.append(cells)

    # Single-pixel components form the small key pattern in the top-left.
    key_cells = [cells[0] for cells in components if len(cells) == 1]
    if not key_cells:
        return out

    key_rows = sorted({r for r, _ in key_cells})
    key_cols = sorted({c for _, c in key_cells})
    kr = {r: i for i, r in enumerate(key_rows)}
    kc = {c: i for i, c in enumerate(key_cols)}

    key = [[bg] * len(key_cols) for _ in key_rows]
    for r, c in key_cells:
        key[kr[r]][kc[c]] = grid[r][c]

    # Larger components are the already-placed blocks.
    blocks = []
    for cells in components:
        if len(cells) <= 1:
            continue
        rs = [r for r, _ in cells]
        cs = [c for _, c in cells]
        r0, r1 = min(rs), max(rs)
        c0, c1 = min(cs), max(cs)
        h = r1 - r0 + 1
        w = c1 - c0 + 1
        # Keep only square, solid blocks.
        if h == w and len(cells) == h * w:
            blocks.append((r0, c0, h, grid[r0][c0]))

    if not blocks:
        return out

    # Block size and grid spacing.
    block_size = blocks[0][2]
    rows = sorted({b[0] for b in blocks})
    cols = sorted({b[1] for b in blocks})

    def spacing(vals):
        if len(vals) < 2:
            return None
        diffs = [vals[i + 1] - vals[i] for i in range(len(vals) - 1) if vals[i + 1] > vals[i]]
        return min(diffs) if diffs else None

    dx = spacing(cols)
    dy = spacing(rows)
    if dx is None and dy is None:
        dx = dy = block_size + 1
    elif dx is None:
        dx = dy
    elif dy is None:
        dy = dx

    # Relative coordinates of existing blocks in their own grid.
    min_r = min(rows)
    min_c = min(cols)
    existing = {}
    for r, c, _, col in blocks:
        i = (r - min_r) // dy
        j = (c - min_c) // dx
        existing[(i, j)] = col

    # Find where this existing subgrid matches the key.
    best = None
    for ri in range(len(key)):
        for ci in range(len(key[0])):
            ok = True
            for (i, j), col in existing.items():
                rr, cc = ri + i, ci + j
                if rr >= len(key) or cc >= len(key[0]) or key[rr][cc] != col:
                    ok = False
                    break
            if ok:
                # Prefer the top-left-most match.
                if best is None or (ri, ci) < best:
                    best = (ri, ci)

    if best is None:
        return out

    ri, ci = best
    target_r0 = min_r - ri * dy
    target_c0 = min_c - ci * dx

    # Fill the full key pattern as blocks.
    for i, row in enumerate(key):
        for j, col in enumerate(row):
            if col == bg:
                continue
            r = target_r0 + i * dy
            c = target_c0 + j * dx
            if r < 0 or c < 0 or r + block_size > H or c + block_size > W:
                continue
            for y in range(r, r + block_size):
                for x in range(c, c + block_size):
                    out[y][x] = col

    return out

