                    comp_holes.setdefault(k, set()).add(bg[r, c])

    # Build output
    for r in range(h):
        for c in range(w):
            if a[r, c] == 1:
                k = comp[r, c]
                if k in comp_holes:
                    out[r, c] = 8
                else:
                    out[r, c] = 1
            elif bg[r, c] not in outside:
                # enclosed background: hole
                out[r, c] = 6
            else:
                # outside background: put 2 if 8-adjacent to any 1
                if any(
                    0 <= r + dy < h and 0 <= c + dx < w and a[r + dy, c + dx] == 1
                    for dy in (-1, 0, 1)
                    for dx in (-1, 0, 1)
                    if (dy, dx) != (0, 0)
                ):
                    out[r, c] = 2
                else:
                    out[r, c] = 4

    return out.tolist()

import sys
from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Background is the most frequent colour.
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Collect bounding boxes for every non-background colour.
    boxes = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg:
                continue
            if v not in boxes:
                boxes[v] = [r, r, c, c]
            else:
                b = boxes[v]
                b[0] = min(b[0], r)
                b[1] = max(b[1], r)
                b[2] = min(b[2], c)
                b[3] = max(b[3], c)

    colours = list(boxes.keys())
    n = len(colours)

    # Union colours that are part of the same object.
    # Two colours are linked if their bounding boxes overlap or touch.
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    def close(b1, b2):
        r1, r2, c1, c2 = b1
        r3, r4, c3, c4 = b2
        # Separated by at least one full row or column?
        if r3 > r2 + 1 or r1 > r4 + 1:
            return False
        if c3 > c2 + 1 or c1 > c4 + 1:
            return False
        return True

    for i in range(n):
        for j in range(i + 1, n):
            if close(boxes[colours[i]], boxes[colours[j]]):
                union(i, j)

    clusters = {}
    for i, col in enumerate(colours):
        clusters.setdefault(find(i), []).append(col)
    clusters = list(clusters.values())

    # Choose the monochrome cluster as the mask.
    # Fallbacks are included for robustness, though the examples always
    # have exactly one single-colour mask object.
    if len(clusters) == 2:
        single = [cl for cl in clusters if len(cl) == 1]
        if len(single) == 1:
            mask_cols = single[0]
            pattern_cols = [c for cl in clusters if cl is not single[0] for c in cl]
        else:
            # Fallback: fewer colours, then smaller total pixel count.
            def key(cl):
                cnt = sum(1 for row in grid for x in row if x in cl)
                return (len(cl), cnt)
            clusters_sorted = sorted(clusters, key=key)
            mask_cols = clusters_sorted[0]
            pattern_cols = clusters_sorted[1]
    else:
        # Fallback for unexpected extra clusters: use the smallest cluster
        # as mask and everything else as pattern.
        def key(cl):
            cnt = sum(1 for row in grid for x in row if x in cl)
            return (len(cl), cnt)
        clusters_sorted = sorted(clusters, key=key)
        mask_cols = clusters_sorted[0]
        pattern_cols = [c for cl in clusters_sorted[1:] for c in cl]

    # Bounding box of the mask.
    mr0 = min(boxes[c][0] for c in mask_cols)
    mr1 = max(boxes[c][1] for c in mask_cols)
    mc0 = min(boxes[c][2] for c in mask_cols)
    mc1 = max(boxes[c][3] for c in mask_cols)

    # Bounding box of the pattern tile.
    pr0 = min(boxes[c][0] for c in pattern_cols)
    pr1 = max(boxes[c][1] for c in pattern_cols)
    pc0 = min(boxes[c][2] for c in pattern_cols)
    pc1 = max(boxes[c][3] for c in pattern_cols)

    mask_h = mr1 - mr0 + 1
    mask_w = mc1 - mc0 + 1
    pat_h = pr1 - pr0 + 1
    pat_w = pc1 - pc0 + 1

    pattern = [
        [grid[pr0 + i][pc0 + j] for j in range(pat_w)]
        for i in range(pat_h)
    ]

    out = [[bg] * (mask_w * pat_w) for _ in range(mask_h * pat_h)]

    for i in range(mask_h):
        for j in range(mask_w):
            if grid[mr0 + i][mc0 + j] in mask_cols:
                for a in range(pat_h):
                    for b in range(pat_w):
                        out[(i * pat_h) + a][(j * pat_w) + b] = pattern[a][b]

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import sys
    from collections import Counter, deque

    sys.setrecursionlimit(1000000)

    # Normalize input to a plain 2D list of ints.
    g = [[int(x) for x in row] for row in grid]
    H, W = len(g), len(g[0])

    # Background is the dominant border colour (fallback: most common overall).
    border = []
    for r in range(H):
        border.append(g[r][0])
        border.append(g[r][W - 1])
    for c in range(W):
        border.append(g[0][c])
        border.append(g[H - 1][c])
    bg = Counter(border).most_common(1)[0][0]

    # 8-connected components of non-background cells.
    seen = [[False] * W for _ in range(H)]
    comps = []

    for r in range(H):
        for c in range(W):
            if g[r][c] == bg or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == 0 and dx == 0:
                            continue
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if not seen[ny][nx] and g[ny][nx] != bg:
                                seen[ny][nx] = True
                                q.append((ny, nx))
            comps.append(cells)

    # If the mask is internally disconnected, merge components that clearly
    # belong to the same rectangular object.
    def bbox(cells):
        rs = [r for r, _ in cells]
        cs = [c for _, c in cells]
        return min(rs), max(rs), min(cs), max(cs)

    def boxes_touch(b1, b2, gap=1):
        r1, r2, c1, c2 = b1
        r3, r4, c3, c4 = b2
        return (r1 - gap <= r4 and r3 - gap <= r2 and
                c1 - gap <= c4 and c3 - gap <= c2)

    if len(comps) > 2:
        boxes = [bbox(comp) for comp in comps]
        parent = list(range(len(comps)))

        def find(a):
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[rb] = ra

        for i in range(len(comps)):
            for j in range(i + 1, len(comps)):
                if boxes_touch(boxes[i], boxes[j]):
                    union(i, j)

        merged = {}
        for i, comp in enumerate(comps):
            merged.setdefault(find(i), []).extend(comp)
        comps = list(merged.values())

    # Extract each component's bounding box and colours.
    objects = []
    for comp in comps:
        r1, r2, c1, c2 = bbox(comp)
        sub = [
            [g[r][c] for c in range(c1, c2 + 1)]
            for r in range(r1, r2 + 1)
        ]
        colors = {x for row in sub for x in row if x != bg}
        objects.append({
            "sub": sub,
            "colors": colors,
            "area": (r2 - r1 + 1) * (c2 - c1 + 1),
            "cells": len(comp),
        })

    # The mask is the object made of a single non-background colour.
    # The tile is the other object.
    mask = None
    tile = None
    single = [o for o in objects if len(o["colors"]) == 1]
    multi = [o for o in objects if len(o["colors"]) > 1]

    if len(single) == 1 and len(multi) == 1:
        mask, tile = single[0], multi[0]
    else:
        # Fallback: choose the smaller bounding box as the mask.
        objects.sort(key=lambda o: o["area"])
        mask, tile = objects[0], objects[1]

    mask_grid = mask["sub"]
    tile_grid = tile["sub"]
    mask_fg = next(iter(mask["colors"]))

    mh, mw = len(mask_grid), len(mask_grid[0])
    th, tw = len(tile_grid), len(tile_grid[0])

    out = [[bg] * (mw * tw) for _ in range(mh * th)]

    for i in range(mh):
        for j in range(mw):
            if mask_grid[i][j] == mask_fg:
                for a in range(th):
                    for b in range(tw):
                        out[i * th + a][j * tw + b] = tile_grid[a][b]

    return out
